package com.mutang.xunxi;

import android.app.*;
import android.text.InputType;
import android.view.View;
import android.widget.*;

final class CloudSyncPanel {
    final MainActivity activity;final CloudSettings settings;boolean busy;
    CloudSyncPanel(MainActivity a){activity=a;settings=new CloudSettings(a);}
    boolean active(){return !activity.isFinishing()&&!activity.isDestroyed();}
    void card(LinearLayout parent){LinearLayout c=activity.card();activity.add(c,activity.text("云同步",17,MainActivity.TEXT,true));activity.gap(c,7);activity.add(c,activity.text("支持坚果云、Nextcloud / ownCloud 与通用 WebDAV。同步订阅、历史与已读状态，不上传账号密码。",13,MainActivity.MUTED,false));activity.gap(c,10);activity.add(c,activity.text(settings.configured()?(settings.last()>0?"已连接 · 上次同步 "+activity.format(settings.last(),"MM-dd HH:mm"):"已配置 · 尚未同步"):"尚未配置云同步",12,settings.configured()?MainActivity.GREEN:MainActivity.MUTED,true));activity.gap(c,10);activity.add(c,activity.action("配置云端",false,()->configure()));if(settings.configured()){activity.gap(c,8);activity.add(c,activity.action(busy?"同步中…":"立即同步",true,()->sync(true)));Switch sw=new Switch(activity);sw.setText("打开应用时自动同步");sw.setChecked(settings.automatic());sw.setOnCheckedChangeListener((v,on)->{settings.auto(on);if(on)sync(false);});activity.add(c,sw);activity.gap(c,7);activity.add(c,activity.action("断开云同步",false,()->{if(busy){Toast.makeText(activity,"请等同步完成",Toast.LENGTH_SHORT).show();return;}new AlertDialog.Builder(activity).setTitle("断开云同步？").setMessage("仅清除本机云端连接设置；本地订阅和云端同步文件都不会删除。").setNegativeButton("取消",null).setPositiveButton("断开",(d,w)->{settings.clear();activity.render(true);}).show();}));}activity.add(parent,c);activity.gap(parent,12);}
    void configure(){if(busy){Toast.makeText(activity,"请等同步完成后再配置",Toast.LENGTH_SHORT).show();return;}CloudSyncClient.Config old=null;try{old=settings.load();}catch(Exception ignored){}final CloudSyncClient.Config previous=old;LinearLayout box=activity.column();activity.pad(box,20,6,20,4);Spinner provider=new Spinner(activity);String[] choices={"坚果云","Nextcloud / ownCloud","通用 WebDAV"};provider.setAdapter(new ArrayAdapter<String>(activity,android.R.layout.simple_spinner_dropdown_item,choices));activity.add(box,provider);EditText address=new EditText(activity);address.setSingleLine(true);address.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);address.setHint("HTTPS WebDAV 文件夹地址");activity.add(box,address);EditText user=new EditText(activity);user.setSingleLine(true);user.setHint("账号 / 邮箱");activity.add(box,user);EditText pass=new EditText(activity);pass.setSingleLine(true);pass.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);pass.setHint(previous==null?"应用密码":"应用密码（留空保留已有密码）");activity.add(box,pass);TextView hint=activity.text("坚果云需在网盘先创建 Xunji 文件夹，然后使用第三方应用密码。其他 WebDAV 请选择已存在的可写文件夹。同步会将订阅、文章标题及已读记录上传到你配置的云端。",12,MainActivity.MUTED,false);activity.gap(box,8);activity.add(box,hint);if(previous!=null){address.setText(previous.url);user.setText(previous.user);provider.setSelection(previous.url.equals(CloudSyncClient.NUTSTORE)?0:2);}else address.setText(CloudSyncClient.NUTSTORE);provider.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){boolean first=true;public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){if(first){first=false;return;}if(pos==0)address.setText(CloudSyncClient.NUTSTORE);else address.setText("");}public void onNothingSelected(android.widget.AdapterView<?> p){}});
        AlertDialog dialog=new AlertDialog.Builder(activity).setTitle("配置云同步").setView(box).setNegativeButton("取消",null).setPositiveButton("保存",null).create();dialog.setOnShowListener(x->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{try{String url=CloudSyncClient.folder(address.getText().toString()),name=user.getText().toString().trim(),password=pass.getText().toString();if(password.isEmpty()&&previous!=null&&url.equals(previous.url)&&name.equals(previous.user))password=previous.password;settings.save(new CloudSyncClient.Config(url,name,password));dialog.dismiss();activity.render(true);Toast.makeText(activity,"配置已保存，点击立即同步",Toast.LENGTH_SHORT).show();}catch(Exception e){address.setError(e.getMessage()==null?"配置无效":e.getMessage());}}));dialog.show();}
    void startup(){if(settings.configured()&&settings.automatic()&&System.currentTimeMillis()-settings.last()>15*60*1000L)sync(false);}
    void sync(boolean manual){if(busy)return;CloudSyncClient.Config cfg;try{cfg=settings.load();if(cfg==null){if(manual)configure();return;}}catch(Exception e){if(manual)message("无法读取云同步配置","请重新配置账号与应用密码。");return;}busy=true;if(active())activity.render(true);new Thread(()->{try{CloudSyncClient.sync(cfg,activity.store);settings.synced();activity.runOnUiThread(()->{busy=false;if(active()){RefreshJob.schedule(activity,true);activity.render(true);if(manual)message("同步完成","已合并本地与云端订阅、历史记录和已读状态。");}});}catch(Exception e){activity.runOnUiThread(()->{busy=false;if(active()){activity.render(true);if(manual)message("同步失败",e.getMessage()==null?"请检查网络或 WebDAV 配置。":e.getMessage());}});}},"xunji-cloud-sync").start();}
    void message(String t,String m){if(active())new AlertDialog.Builder(activity).setTitle(t).setMessage(m).setPositiveButton("确定",null).show();}
}
